/**
 * The C# SDK's package, as files (contract 45 §4.2-§4.4, §7.5): the file set, the manifest and the root
 * `.editorconfig` byte for byte, the markers and no `<auto-generated`, the options' defaults, effects and refusals,
 * one namespace across every file, each stream kind's runtime files (contract 50 §2: the Fb1 refusal is gone),
 * determinism, the collision refusal, the method and client docs (Fb4: no `<param>`), the exact client members, and
 * which call plans throw.
 */
import { describe, expect, it } from "vitest"
import minimal from "../../ir/__fixtures__/specs/python/minimal.json" with { type: "json" }
import { FIXTURES } from "./__fixtures__/documents.ts"
import type { CSharpCallPlan } from "./sdk-plan.ts"
import { csharpCallPlans, type CSharpSdkOptions, generateCSharpSdk } from "./sdk.ts"
import { runtimeFileNames } from "./transport.ts"

type Json = Record<string, unknown>
type Files = Readonly<Record<string, string>>

const MARK_CS = "// @generated by honey. DO NOT EDIT."
const MARK_CSPROJ = "<!-- @generated by honey. DO NOT EDIT. -->"
const MARK_EDITORCONFIG = "# @generated by honey. DO NOT EDIT."

const filesOf = (document: Json, options?: CSharpSdkOptions): Files => generateCSharpSdk(document, options).files
const surface = (): Json => FIXTURES.surface.document()
const SURFACE: CSharpSdkOptions = FIXTURES.surface.options

/** §4.3's manifest for package `id` in namespace `namespace` at `version`. */
const csproj = (id: string, namespace: string, version: string) => `${MARK_CSPROJ}
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>net10.0</TargetFramework>
    <AssemblyName>${id}</AssemblyName>
    <RootNamespace>${namespace}</RootNamespace>
    <PackageId>${id}</PackageId>
    <Version>${version}</Version>
    <Nullable>enable</Nullable>
    <ImplicitUsings>disable</ImplicitUsings>
    <TreatWarningsAsErrors>true</TreatWarningsAsErrors>
    <IsAotCompatible>true</IsAotCompatible>
    <GenerateDocumentationFile>true</GenerateDocumentationFile>
    <NoWarn>$(NoWarn);CS1591</NoWarn>
  </PropertyGroup>
</Project>
`

/** §4.3's `.editorconfig`: `root = true`, so no parent file reaches the emitted sources (R6). */
const EDITORCONFIG = `${MARK_EDITORCONFIG}
root = true

[*.cs]
charset = utf-8
end_of_line = lf
indent_size = 4
indent_style = space
insert_final_newline = true
`

/** The marker line 1 of file `name` must hold, by its kind; undefined for a kind the package never ships. */
const markOf = (name: string) =>
	name.endsWith(".cs")
		? MARK_CS
		: name.endsWith(".csproj")
			? MARK_CSPROJ
			: name === ".editorconfig"
				? MARK_EDITORCONFIG
				: undefined

/** The files whose line 1 is not the marker of their kind. */
const unmarked = (files: Files) =>
	Object.entries(files)
		.filter(([name, text]) => markOf(name) === undefined || text.split("\n")[0] !== markOf(name))
		.map(([name]) => name)

/** Each distinct set of `namespace` lines a `.cs` file holds, joined: one entry, one line, when all agree (Fb2). */
const namespaces = (files: Files) => [
	...new Set(
		Object.entries(files)
			.filter(([name]) => name.endsWith(".cs"))
			.map(([, text]) =>
				text
					.split("\n")
					.filter((line) => line.startsWith("namespace "))
					.join(" | "),
			),
	),
]

/** The `public sealed class … : IDisposable` names in Client.cs, and the `JsonSerializerContext` in JsonContext.cs. */
const names = (files: Files) => ({
	client: /^public sealed class (\w+) : IDisposable$/m.exec(files["Client.cs"] ?? "")?.[1],
	context: /^public sealed partial class (\w+) : JsonSerializerContext$/m.exec(files["JsonContext.cs"] ?? "")?.[1],
})

/** The document with its paths, and the methods inside each, in reverse order. */
const reordered = (document: Json): Json => ({
	...document,
	paths: Object.fromEntries(
		Object.entries(document.paths as Record<string, Json>)
			.toReversed()
			.map(([key, item]) => [key, Object.fromEntries(Object.entries(item).toReversed())]),
	),
})

/** Every document the determinism check emits, with its options: `minimal` and each registry document. */
const DOCUMENTS: (readonly [name: string, document: () => Json, options: CSharpSdkOptions | undefined])[] = [
	["python/minimal", () => minimal as Json, undefined],
	...Object.entries(FIXTURES).flatMap(([key, entry]) =>
		"document" in entry
			? [[`FIXTURES.${key}`, entry.document, "options" in entry ? entry.options : undefined] as const]
			: [],
	),
]

/** A one-operation document: `operationId` under `method` at `/x`. */
const single = (operationId: string, operation: Json, method = "post"): Json => ({
	info: { title: "Refused", version: "1" },
	openapi: "3.1.0",
	paths: { "/x": { [method]: { operationId, ...operation } } },
})

const STRING = { type: "string" }
const content = (type: string, schema: Json = STRING) => ({ content: { [type]: { schema } } })
const answer = (type: string, schema?: Json) => ({
	responses: { 200: { description: "ok", ...content(type, schema) } },
})
const SOCKET = { responses: { 101: { description: "Switching Protocols" } }, "x-websocket": true }

/** Each stream kind phase b refused (Fb1), as its own one-op document, which phase d emits (contract 50 §2). */
const STREAMED = {
	realtime: single("realtime.connect", { ...SOCKET, "x-realtime": true }, "get"),
	sse: single("events.stream", answer("text/event-stream"), "get"),
	ws: single("ws.subscribe", SOCKET, "get"),
} as const

/** The runtime file names `document`'s package ships under `Runtime/`, in key order. */
const shippedRuntime = (document: Json) =>
	Object.keys(filesOf(document))
		.filter((name) => name.startsWith("Runtime/"))
		.map((name) => name.slice("Runtime/".length))

/** `users.create` is callable and the namespace of `users.create.draft` (Python's 87ccdf5091 input). */
const COLLISION: Json = {
	info: { title: "Collision", version: "1" },
	openapi: "3.1.0",
	paths: Object.fromEntries(
		[
			["/users", "users.create"],
			["/users/draft", "users.create.draft"],
		].map(([path, operationId]) => [path, { post: { operationId, responses: { 204: { description: "done" } } } }]),
	),
}

/** One op declaring 404, 409 and 418: two statuses with a class of their own, one without (Fb14). */
const RAISES: Json = {
	info: { title: "Raises", version: "1" },
	openapi: "3.1.0",
	paths: {
		"/widgets/{id}": {
			get: {
				operationId: "widgets.get",
				parameters: [{ in: "path", name: "id", required: true, schema: STRING }],
				responses: Object.fromEntries([
					[200, { description: "ok", ...content("application/json") }],
					...[404, 409, 418].map((status) => [status, { description: `status ${status}` }]),
				]),
			},
		},
	},
}

/** An op whose summary holds XML's specials: the doc text goes through `csDocLines` (F2, Q7's CS1570). */
const ESCAPED = single("notes.get", { ...answer("application/json"), summary: "a < b & c" }, "get")

/** The `///` lines directly above the first `public` member named `member` in `text`, in order. */
function docAbove(text: string, member: string): string[] {
	const lines = text.split("\n")
	const at = lines.findIndex((line) => new RegExp(`^ {4}public \\S.* ${member}\\(`).test(line))
	if (at < 0) return [`no member ${member}`]
	let start = at
	while (start > 0 && (lines[start - 1] ?? "").startsWith("    ///")) start -= 1
	return lines.slice(start, at)
}

/** The docs above RAISES' `GetAsync` in throw or safe mode. */
const raisesDoc = (throwOnError: boolean) => docAbove(filesOf(RAISES, { throwOnError })["Client.cs"] ?? "", "GetAsync")

/** `surface`'s Client.cs lines under `options`. */
const clientLines = (options: CSharpSdkOptions) => (filesOf(surface(), options)["Client.cs"] ?? "").split("\n")

/** Each distinct `throws` of the document's call plans. */
const throwsOf = (document: Json, options?: CSharpSdkOptions) => [
	...new Set(Object.values<CSharpCallPlan>(csharpCallPlans(document, options)).map((plan) => plan.throws)),
]

describe("generateCSharpSdk: the package's files", () => {
	it("emits the .editorconfig, the manifest, Client.cs, JsonContext.cs, Types.cs and the runtime under Runtime/, keyed in code-unit order", () => {
		const keys = Object.keys(filesOf(minimal))
		const expected = [
			".editorconfig",
			"Client.cs",
			"HoneySdk.csproj",
			"JsonContext.cs",
			...runtimeFileNames({ realtime: false, ws: false }).map((name: string) => `Runtime/${name}`),
			"Types.cs",
		].sort()
		expect({ keys, sorted: [...keys].sort() }).toEqual({ keys: expected, sorted: expected })
	})

	it("writes §4.3's manifest byte for byte: the package id as the assembly name, the namespace, net10.0, the doc file with only CS1591 off", () => {
		expect(filesOf(surface(), SURFACE)["Acme.Sdk.csproj"]).toBe(csproj("Acme.Sdk", "Acme", "0.1.0"))
	})

	it("writes §4.3's root .editorconfig byte for byte", () => {
		expect(filesOf(minimal)[".editorconfig"]).toBe(EDITORCONFIG)
	})

	it("marks line 1 of every .cs file, the manifest and the .editorconfig @generated, and never writes <auto-generated or a .g.cs or .generated.cs name", () => {
		const packages = [filesOf(minimal), filesOf(surface(), SURFACE), filesOf(FIXTURES.fixtures.document())]
		expect({
			autoGenerated: packages.flatMap((files) =>
				Object.entries(files)
					.filter(([, text]) => text.includes("<auto-generated"))
					.map(([name]) => name),
			),
			names: packages.flatMap((files) => Object.keys(files).filter((name) => /\.(?:g|generated)\.cs$/.test(name))),
			unmarked: packages.flatMap(unmarked),
		}).toEqual({ autoGenerated: [], names: [], unmarked: [] })
	})

	it("emits each stream kind, and ships the WebSocket files for a WebSocket or realtime op and the realtime files only for a realtime op (contract 50 §2)", () => {
		const shipped = {
			realtime: shippedRuntime(STREAMED.realtime),
			sse: shippedRuntime(STREAMED.sse),
			ws: shippedRuntime(STREAMED.ws),
		}
		expect(shipped).toEqual({
			realtime: runtimeFileNames({ realtime: true, ws: false }),
			sse: runtimeFileNames({ realtime: false, ws: false }),
			ws: runtimeFileNames({ realtime: false, ws: true }),
		})
		/* three distinct sets, so a mix the emitter ignores cannot pass */
		expect(new Set(Object.values(shipped).map((files) => files.join())).size).toBe(3)
	})

	it("puts every .cs file, the runtime's among them, in the SDK's own namespace, once (Fb2)", () => {
		expect([namespaces(filesOf(surface(), SURFACE)), namespaces(filesOf(minimal))]).toEqual([
			["namespace Acme;"],
			["namespace HoneySdk;"],
		])
	})
})

describe("generateCSharpSdk: the options (Fb3)", () => {
	it("defaults to package HoneySdk in namespace HoneySdk at 0.1.0, with HoneySdkClient and HoneySdkJsonContext", () => {
		const files = filesOf(minimal)
		expect({ csproj: files["HoneySdk.csproj"], ...names(files) }).toEqual({
			client: "HoneySdkClient",
			context: "HoneySdkJsonContext",
			csproj: csproj("HoneySdk", "HoneySdk", "0.1.0"),
		})
	})

	it("names the client after the last segment of a dotted namespace, and keeps the package id", () => {
		const files = filesOf(minimal, { rootNamespace: "Contoso.Widgets" })
		expect({ csproj: files["HoneySdk.csproj"], namespaces: namespaces(files), ...names(files) }).toEqual({
			client: "WidgetsClient",
			context: "WidgetsJsonContext",
			csproj: csproj("HoneySdk", "Contoso.Widgets", "0.1.0"),
			namespaces: ["namespace Contoso.Widgets;"],
		})
	})

	it("takes packageId, rootNamespace, clientName and version into the manifest's name, the namespace and the class names", () => {
		const files = filesOf(minimal, {
			clientName: "ShopClient",
			packageId: "Acme.Sdk",
			rootNamespace: "Acme",
			version: "2.0.0-rc.1",
		})
		expect({ csproj: files["Acme.Sdk.csproj"], ...names(files) }).toEqual({
			client: "ShopClient",
			context: "ShopJsonContext",
			csproj: csproj("Acme.Sdk", "Acme", "2.0.0-rc.1"),
		})
	})

	it("takes a package id of 100 characters, NuGet's limit", () => {
		expect(Object.keys(filesOf(minimal, { packageId: "X".repeat(100) }))).toContain(`${"X".repeat(100)}.csproj`)
	})

	it.each([
		["packageId", "Bad Id!"],
		["packageId", "a..b"],
		["packageId", "x".repeat(101)],
		["rootNamespace", "System.X"],
		["rootNamespace", "class"],
		["rootNamespace", "A.2b"],
		["clientName", "lower"],
		["version", "1.0"],
	] as const)("refuses the %s %j, naming it", (option, value) => {
		expect(() => generateCSharpSdk(minimal, { [option]: value })).toThrow(`Invalid ${option}: "${value}"`)
	})
})

describe("generateCSharpSdk: determinism and conflicts", () => {
	it.each(DOCUMENTS)("emits identical files for %s twice and for its paths reordered", (_name, document, options) => {
		const { files } = generateCSharpSdk(document(), options)
		expect([
			generateCSharpSdk(document(), options).files,
			generateCSharpSdk(reordered(document()), options).files,
		]).toEqual([files, files])
	})

	it("refuses an id that is both callable and a namespace, naming both ids", () => {
		expect(() => generateCSharpSdk(COLLISION)).toThrow(/operationId conflict.*users\.create.*users\.create\.draft/)
	})
})

describe("generateCSharpSdk: docs (Fb4)", () => {
	it("documents a method with its summary and its description as remarks", () => {
		expect(docAbove(filesOf(minimal)["Client.cs"] ?? "", "PingAsync")).toEqual([
			"    /// <summary>Health check</summary>",
			"    /// <remarks>Returns a pong string</remarks>",
		])
	})

	it("escapes the doc text as XML through csDocLines", () => {
		expect(docAbove(filesOf(ESCAPED)["Client.cs"] ?? "", "GetAsync")).toEqual([
			"    /// <summary>a &lt; b &amp; c</summary>",
		])
	})

	it("lists each declared error status's exception in throw mode, ascending, UnexpectedStatusException for one without a class, and none in safe mode", () => {
		expect({ safe: raisesDoc(false), thrown: raisesDoc(true) }).toEqual({
			safe: [],
			thrown: [
				'    /// <exception cref="NotFoundException">HTTP 404</exception>',
				'    /// <exception cref="ConflictException">HTTP 409</exception>',
				'    /// <exception cref="UnexpectedStatusException">HTTP 418</exception>',
			],
		})
	})

	it("documents the client with its name and the API's description", () => {
		const client = (filesOf(surface(), SURFACE)["Client.cs"] ?? "").split("\n")
		const at = client.indexOf("public sealed class AcmeClient : IDisposable")
		expect(client.slice(at - 2, at)).toEqual([
			"/// <summary>The Acme client, generated by honey.</summary>",
			"/// <remarks>The Acme API.</remarks>",
		])
	})

	it("writes no <param> tag in any emitted file", () => {
		const emitted = [
			filesOf(minimal),
			filesOf(RAISES),
			filesOf(surface(), SURFACE),
			filesOf(FIXTURES.fixtures.document()),
		].flatMap((files) => ["Client.cs", "JsonContext.cs", "Types.cs"].map((name) => files[name] ?? ""))
		expect(emitted.filter((text) => text.includes("<param"))).toEqual([])
	})
})

describe("generateCSharpSdk: Client.cs's members (§4.4)", () => {
	it("constructs the transport and the resources once, and disposes the transport", () => {
		expect(clientLines(SURFACE)).toEqual(
			expect.arrayContaining([
				"public sealed class AcmeClient : IDisposable",
				"    public AcmeClient(ClientConfig? config = null)",
				"        _t = new Transport(config ?? new ClientConfig(), _defaults);",
				"        Orgs = new OrgsResource(_t);",
				"        Users = new UsersResource(_t);",
				"    public OrgsResource Orgs { get; }",
				"    public void Dispose() => _t.Dispose();",
				"    internal OrgsMembersNotesResource(Transport t)",
			]),
		)
	})

	it("writes the NOTES op: path params in path order, the body, then the optional query and header params, the call on the next line", () => {
		expect(clientLines(SURFACE)).toEqual(
			expect.arrayContaining([
				'    private static readonly Operation _create = new("POST", "/orgs/{org}/members/{member}/notes", ["org", "member"], Idempotent: false);',
				'    /// <exception cref="ConflictException">HTTP 409</exception>',
				"    public Task<Note> CreateAsync(string org, string member, NoteInput body, string? tag = null, string? xTrace = null, RequestOptions? options = null, CancellationToken cancellationToken = default) =>",
				'        _t.CallAsync(_create, new([org, member], [Arg.Of("tag", tag, AcmeJsonContext.Default.String)], [Arg.Of("X-Trace", xTrace, AcmeJsonContext.Default.String)], Body.Json(body, AcmeJsonContext.Default.NoteInput), null, options), AcmeJsonContext.Default.Note, cancellationToken);',
			]),
		)
	})

	it("writes the root getUser and the idempotent users.create with its idempotencyKey", () => {
		expect(clientLines(SURFACE)).toEqual(
			expect.arrayContaining([
				'    private static readonly Operation _getUser = new("GET", "/users/{id}", ["id"], Idempotent: false);',
				"    public Task<User> GetUserAsync(string id, RequestOptions? options = null, CancellationToken cancellationToken = default) =>",
				"        _t.CallAsync(_getUser, new([id], [], [], null, null, options), AcmeJsonContext.Default.User, cancellationToken);",
				'    private static readonly Operation _create = new("POST", "/users", [], Idempotent: true);',
				"    public Task<User> CreateAsync(UserCreateInput body, string? idempotencyKey = null, RequestOptions? options = null, CancellationToken cancellationToken = default) =>",
				"        _t.CallAsync(_create, new([], [], [], Body.Json(body, AcmeJsonContext.Default.UserCreateInput), idempotencyKey, options), AcmeJsonContext.Default.User, cancellationToken);",
			]),
		)
	})

	it("answers SdkResult through ResultAsync in safe mode", () => {
		expect(clientLines({ ...SURFACE, throwOnError: false })).toEqual(
			expect.arrayContaining([
				"    public Task<SdkResult<User>> GetUserAsync(string id, RequestOptions? options = null, CancellationToken cancellationToken = default) =>",
				"        _t.ResultAsync(_getUser, new([id], [], [], null, null, options), AcmeJsonContext.Default.User, cancellationToken);",
			]),
		)
	})
})

describe("csharpCallPlans: which plans throw", () => {
	it("marks every plan throws: false under throwOnError: false, and throws: true otherwise", () => {
		const safe = FIXTURES["fixtures-safe"]
		expect({
			fixtures: throwsOf(FIXTURES.fixtures.document()),
			fixturesSafe: throwsOf(safe.document(), safe.options),
			surface: throwsOf(surface(), SURFACE),
			surfaceSafe: throwsOf(surface(), { ...SURFACE, throwOnError: false }),
		}).toEqual({ fixtures: [true], fixturesSafe: [false], surface: [true], surfaceSafe: [false] })
	})
})
